import { existsSync } from "node:fs";
import { defineConfig } from "drizzle-kit";

// drizzle-kit doesn't read .env on its own; the environment wins over the file.
if (existsSync(".env")) process.loadEnvFile(".env");

/**
 * One schema, one migration history: Better Auth's tables
 * (`auth-schema.ts`, generated by `bun run auth:generate`) and the app's
 * (`app-schema.ts`). After changing either:
 *
 *   bun run db:generate   # writes the SQL migration to ./drizzle
 *   bun run db:migrate    # applies it
 */
export default defineConfig({
	dialect: "postgresql",
	schema: "./src/database/schema/index.ts",
	out: "./drizzle",
	dbCredentials: { url: process.env.DATABASE_URL ?? "" },
	strict: true,
});
